def candidates(abspts):
 out=[]
 for ki,(k,ref,p) in enumerate(D):
  for sr,sc in abspts:
   for pr,pc in p:
    tr,tc=sr-pr,sc-pc
    if {(tr+r,tc+c) for r,c in p} and set(abspts)<= {(tr+r,tc+c) for r,c in p}:
     cells={(tr+r,tc+c) for r,c in p}
     out.append((k,ref,tr,tc,tuple(sorted(cells))))
 return out
